  arm_rad a "$IMG_RAD_A"  "$RAD_MXFP4" qwen38-27b-mxfp4
  arm_rad b "$IMG_RAD_BC" "$RAD_MXFP4" qwen38-27b-mxfp4
  arm_rad c "$IMG_RAD_BC" "$RAD_IQRV4" qwen38-27b-iq4r-l-v4
  kld_ref_ensure || true
  kld_score_all
fi
print_summary
make_report
echo "campaign done. consolidated results: $RES/results.jsonl  (raw: $RAW/)"
[ -f "$RES/skipped.txt" ] && { echo "--- guard-skipped (over budget) ---"; cat "$RES/skipped.txt"; } || true
fi
